import pandas as pd
import numpy as np


def _is_null(v):
    if v is None:
        return True
    try:
        return bool(pd.isna(v))
    except (TypeError, ValueError):
        return False


def _differs(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_product = inputs["dim_product"]
    stg_product = inputs["stg_product"]

    # Build mutable list of row dicts preserving existing dim_product rows (history + current).
    rows = dim_product.to_dict("records")

    # Map product_id -> index of the current (is_current == 1) row in `rows`.
    current_map = {}
    for idx, r in enumerate(rows):
        if r.get("is_current") == 1:
            current_map[r["product_id"]] = idx

    # Sort staged records by product_id, then update_date ascending (stable, no dedup).
    stg_sorted = stg_product.sort_values(
        by=["product_id", "update_date"], kind="mergesort"
    ).reset_index(drop=True)

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_category = s["category"]
        s_price_band = s["price_band"]
        s_update_date = s["update_date"]

        cur_idx = current_map.get(pid)

        if cur_idx is None:
            new_row = {
                "product_id": pid,
                "category": s_category,
                "price_band": s_price_band,
                "eff_start_date": s_update_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            }
            rows.append(new_row)
            current_map[pid] = len(rows) - 1
        else:
            c = rows[cur_idx]
            changed = _differs(c.get("category"), s_category) or _differs(
                c.get("price_band"), s_price_band
            )
            if changed:
                c["eff_end_date"] = s_update_date
                c["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_category,
                    "price_band": s_price_band,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_map[pid] = len(rows) - 1
            # else: no-op

    out = pd.DataFrame(
        rows,
        columns=[
            "product_id",
            "category",
            "price_band",
            "eff_start_date",
            "eff_end_date",
            "is_current",
        ],
    )

    if len(out) > 0:
        out["product_id"] = out["product_id"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"]).astype(
            "datetime64[us]"
        )
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"]).astype(
            "datetime64[s]"
        )
        out["is_current"] = out["is_current"].astype("int64")
    else:
        out = out.astype(
            {
                "product_id": "int64",
                "category": "object",
                "price_band": "object",
                "eff_start_date": "datetime64[us]",
                "eff_end_date": "datetime64[s]",
                "is_current": "int64",
            }
        )

    return {"dim_product_out": out}
